WITH with_windows AS (SELECT id, customer_id, device, browser, started_at, country, LAST_VALUE(browser) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_browser, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at, id) row_seq FROM sessions) SELECT id, device, browser, country, last_known_browser, row_seq FROM with_windows;
